import concurrent.futures as cf
import email.utils
import html
import json
import os
import re
import subprocess
import sys
import xml.etree.ElementTree as ET
from datetime import datetime, timedelta, timezone

base = sys.argv[1]
feeds = json.load(open(os.path.join(base, "feeds.json"), encoding="utf-8"))
seen_path = os.path.join(base, "seen.json")
seen = {}
if os.path.exists(seen_path):
    try:
        seen = json.load(open(seen_path, encoding="utf-8"))
    except Exception:
        seen = {}

ATOM = "{http://www.w3.org/2005/Atom}"
NOW = datetime.now(timezone.utc)
CUTOFF = NOW - timedelta(days=14)
PER_FEED = 15
TOTAL = 80

def parse_date(s):
    if not s:
        return None
    s = s.strip()
    try:
        dt = email.utils.parsedate_to_datetime(s)
    except Exception:
        dt = None
    if dt is None:
        try:
            dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt

def clean(text, limit):
    text = re.sub(r"<[^>]+>", " ", text or "")
    text = html.unescape(text)
    text = re.sub(r"\s+", " ", text).strip()
    return text[:limit].strip()

def fetch(feed):
    try:
        r = subprocess.run(
            ["curl", "-sL", "--max-time", "20", "-A", "MySuricates-TechRadar/1.0", feed["url"]],
            capture_output=True, timeout=25)
        if r.returncode != 0 or not r.stdout:
            return feed, None, "curl rc=%s" % r.returncode
        root = ET.fromstring(r.stdout)
        items = []
        if root.tag == ATOM + "feed":
            for e in root.findall(ATOM + "entry"):
                link = ""
                for l in e.findall(ATOM + "link"):
                    if l.get("rel") in (None, "alternate"):
                        link = l.get("href") or ""
                        break
                items.append({
                    "title": clean(e.findtext(ATOM + "title"), 120),
                    "link": link.strip(),
                    "date": parse_date(e.findtext(ATOM + "updated") or e.findtext(ATOM + "published")),
                    "teaser": clean(e.findtext(ATOM + "summary") or e.findtext(ATOM + "content"), 160),
                })
        elif root.tag == "rss":
            for e in root.findall("./channel/item"):
                items.append({
                    "title": clean(e.findtext("title"), 120),
                    "link": (e.findtext("link") or "").strip(),
                    "date": parse_date(e.findtext("pubDate")),
                    "teaser": clean(e.findtext("description"), 160),
                })
        else:
            return feed, None, "unbekanntes Root-Element %r" % root.tag
        return feed, items, None
    except Exception as exc:
        return feed, None, "%s: %s" % (type(exc).__name__, exc)

candidates, failures, skipped = [], [], 0
seen_links = set()
with cf.ThreadPoolExecutor(max_workers=8) as pool:
    for feed, items, err in pool.map(fetch, feeds):
        if err:
            failures.append("%s: %s" % (feed["name"], err))
            continue
        kept = 0
        for it in items:
            if kept >= PER_FEED:
                break
            if not it["title"] or not it["link"] or it["date"] is None:
                continue
            if it["date"] < CUTOFF or it["date"] > NOW + timedelta(days=1):
                continue
            if it["link"] in seen:
                skipped += 1
                continue
            if it["link"] in seen_links:
                continue
            seen_links.add(it["link"])
            it["source"] = feed["name"]
            it["topic"] = feed["topic"]
            candidates.append(it)
            kept += 1

# Topic-faires Round-Robin statt reinem Datums-Cut: sonst verdraengen
# hochfrequente Feeds (Azure, HN) die niederfrequenten Topics komplett.
by_topic = {}
for it in candidates:
    by_topic.setdefault(it["topic"], []).append(it)
for lst in by_topic.values():
    lst.sort(key=lambda i: i["date"], reverse=True)
total_found = len(candidates)
picked = []
while len(picked) < TOTAL and any(by_topic.values()):
    for topic in sorted(by_topic):
        if by_topic[topic] and len(picked) < TOTAL:
            picked.append(by_topic[topic].pop(0))
dropped = total_found - len(picked)
candidates = sorted(picked, key=lambda i: (i["topic"], i["date"]), reverse=True)

print("@@KANDIDATEN")
for it in candidates:
    print("- [%s] %s | %s | %s | %s | %s" % (
        it["topic"], it["date"].date().isoformat(), it["source"],
        it["title"], it["link"], it["teaser"] or "-"))
print("@@AUSFAELLE")
if failures:
    for f in failures:
        print("- " + f)
else:
    print("- keine")
print("@@STATS")
print("%d Kandidaten aus %d Feeds; %d Feed-Ausfaelle; %d bereits gemeldet; %d ueber Gesamt-Cap verworfen"
      % (len(candidates), len(feeds), len(failures), skipped, dropped))
