#!/usr/bin/env python3
"""Tech-Radar Renderer: curate/deepen-JSON + collect-Meta -> eine HTML-Seite + Index + seen.json.
Aufruf: render.py <workdir> <outdir>"""
import html
import json
import os
import re
import sys
from datetime import date, datetime, timedelta

TOPIC_LABEL = {
    "java": "Java & Spring",
    "frontend": "Frontend",
    "ai": "KI & LLM-Tooling",
    "cloud": "Cloud",
    "general": "Allgemein",
}
TOPIC_ORDER = ["ai", "java", "frontend", "cloud", "general"]


def esc(s):
    return html.escape(str(s or ""), quote=True)


def parse_params(path):
    params, key, buf = {}, None, []
    with open(path, encoding="utf-8") as f:
        for line in f.read().splitlines():
            if line.startswith("@@"):
                if key:
                    params[key] = "\n".join(buf).strip()
                key, buf = line[2:].strip(), []
            else:
                buf.append(line)
    if key:
        params[key] = "\n".join(buf).strip()
    return params


def load_json(path, label):
    """(data, error) - strippt Markdown-Zaeune und Text um das JSON herum."""
    try:
        text = open(path, encoding="utf-8").read().strip()
    except OSError as e:
        return None, "%s: Datei fehlt (%s)" % (label, e)
    if not text:
        return None, "%s: leere Ausgabe" % label
    if text.startswith("```"):
        lines = text.splitlines()[1:]
        while lines and lines[-1].strip().startswith("```"):
            lines = lines[:-1]
        text = "\n".join(lines).strip()
    start, end = text.find("{"), text.rfind("}")
    if start == -1 or end <= start:
        return None, "%s: kein JSON-Objekt gefunden" % label
    try:
        return json.loads(text[start:end + 1]), None
    except json.JSONDecodeError as e:
        return None, "%s: JSON kaputt (%s)" % (label, e)


def parse_collect_meta(path):
    """Liest @@AUSFAELLE / @@STATS aus dem collect-Output."""
    try:
        text = open(path, encoding="utf-8").read()
    except OSError:
        return [], ""
    sections, key, buf = {}, None, []
    for line in text.splitlines():
        if line.startswith("@@"):
            if key:
                sections[key] = buf
            key, buf = line[2:].strip(), []
        else:
            buf.append(line)
    if key:
        sections[key] = buf
    failures = [l[2:].strip() for l in sections.get("AUSFAELLE", []) if l.startswith("- ")]
    failures = [f for f in failures if f and f != "keine"]
    stats = " ".join(l.strip() for l in sections.get("STATS", []) if l.strip())
    return failures, stats


CSS = """
