  --accent:#2f6f4f; --badge-java:#b45309; --badge-frontend:#1d4ed8; --badge-ai:#7c3aed;
  --badge-cloud:#0e7490; --badge-general:#52525b; }
@media (prefers-color-scheme: dark) {
  :root { --bg:#161616; --card:#1f1f1f; --ink:#e8e6e3; --muted:#9a9a9a; --line:#333;
    --accent:#7fbf9f; } }
* { box-sizing:border-box; }
body { margin:0; background:var(--bg); color:var(--ink);
  font:16px/1.55 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; }
main { max-width:920px; margin:0 auto; padding:2.5rem 1.25rem 4rem; }
h1 { font-size:1.7rem; margin:0 0 .25rem; }
h2 { font-size:1.2rem; margin:2.5rem 0 1rem; border-bottom:1px solid var(--line); padding-bottom:.4rem; }
h3 { font-size:1.05rem; margin:0 0 .5rem; }
a { color:var(--accent); text-decoration:none; }
a:hover { text-decoration:underline; }
.sub { color:var(--muted); margin:0 0 .5rem; }
.card { background:var(--card); border:1px solid var(--line); border-radius:10px;
  padding:1.1rem 1.25rem; margin-bottom:1rem; }
.badge { display:inline-block; font-size:.72rem; font-weight:600; letter-spacing:.02em;
  color:#fff; border-radius:99px; padding:.1rem .55rem; vertical-align:middle; }
.badge.java{background:var(--badge-java)} .badge.frontend{background:var(--badge-frontend)}
.badge.ai{background:var(--badge-ai)} .badge.cloud{background:var(--badge-cloud)}
.badge.general{background:var(--badge-general)}
.digest-item { padding:.65rem 0; border-bottom:1px solid var(--line); }
.digest-item:last-child { border-bottom:none; }
.digest-meta { font-size:.8rem; color:var(--muted); }
.why { margin:.15rem 0 0; }
pre { background:rgba(127,127,127,.12); border:1px solid var(--line); border-radius:8px;
  padding: .9rem 1rem; overflow-x:auto; font-size:.85rem; line-height:1.45; }
.quellen { font-size:.88rem; }
.notice { background:rgba(200,150,0,.12); border:1px solid rgba(200,150,0,.4);
  border-radius:8px; padding:.7rem 1rem; }
footer { margin-top:3rem; color:var(--muted); font-size:.8rem; border-top:1px solid var(--line);
  padding-top:1rem; }
