ul.plain li { padding:.3rem 0; }
"""


def render_report(curate, deepen, deepen_err, failures, stats, report_date, run_id):
    kw = report_date.isocalendar()[1]
    parts = []
    parts.append("<main>")
    parts.append("<h1>Tech-Radar &middot; KW %d/%d</h1>" % (kw, report_date.year))
    parts.append('<p class="sub">Ausgabe vom %s &middot; kuratiert nach Stack- und CV-Relevanz</p>'
                 % report_date.strftime("%d.%m.%Y"))

    lernhappen = (deepen or {}).get("lernhappen") or []
    parts.append("<h2>Lernhappen der Woche</h2>")
    if lernhappen:
        for lh in lernhappen:
            parts.append('<div class="card">')
            parts.append("<h3>%s</h3>" % esc(lh.get("title")))
            parts.append("<p><strong>Was ist es?</strong> %s</p>" % esc(lh.get("was")))
            parts.append("<p><strong>Warum relevant?</strong> %s</p>" % esc(lh.get("warum")))
            if lh.get("beispiel"):
                parts.append("<pre>%s</pre>" % esc(lh.get("beispiel")))
            quellen = [q for q in (lh.get("quellen") or []) if q.get("url")]
            if quellen:
                links = " &middot; ".join('<a href="%s">%s</a>' % (esc(q["url"]), esc(q.get("label") or q["url"]))
                                          for q in quellen)
                parts.append('<p class="quellen"><strong>Quellen:</strong> %s</p>' % links)
            parts.append("</div>")
    elif deepen_err:
        parts.append('<p class="notice">Vertiefung fehlgeschlagen (%s) &mdash; diese Ausgabe enthaelt nur den Digest.</p>' % esc(deepen_err))
    else:
        parts.append('<p class="notice">Keine Lernhappen in dieser Ausgabe.</p>')

    digest = (curate or {}).get("digest") or []
    parts.append("<h2>Digest</h2>")
    if digest:
        by_topic = {}
        for item in digest:
            by_topic.setdefault(item.get("topic") or "general", []).append(item)
        for topic in TOPIC_ORDER + sorted(set(by_topic) - set(TOPIC_ORDER)):
            items = by_topic.get(topic)
            if not items:
                continue
            parts.append('<div class="card">')
            parts.append('<h3><span class="badge %s">%s</span></h3>' % (esc(topic), esc(TOPIC_LABEL.get(topic, topic))))
            for it in items:
                parts.append('<div class="digest-item">')
                parts.append('<a href="%s"><strong>%s</strong></a>' % (esc(it.get("url")), esc(it.get("title"))))
                parts.append('<div class="digest-meta">%s &middot; %s</div>' % (esc(it.get("source")), esc(it.get("date"))))
                parts.append('<p class="why">%s</p>' % esc(it.get("why")))
                parts.append("</div>")
            parts.append("</div>")
    else:
        parts.append('<p class="notice">Kein Digest &mdash; Kuratierung lieferte keine Items.</p>')

    gaps = [g for g in ((deepen or {}).get("gaps") or []) if g.get("url")]
    if gaps:
        parts.append("<h2>Web-Fundst&uuml;cke (nicht in den Feeds)</h2>")
        parts.append('<div class="card"><ul class="plain">')
        for g in gaps:
            parts.append('<li><span class="badge %s">%s</span> <a href="%s"><strong>%s</strong></a><p class="why">%s</p></li>'
                         % (esc(g.get("topic") or "general"), esc(TOPIC_LABEL.get(g.get("topic"), g.get("topic") or "Allgemein")),
                            esc(g["url"]), esc(g.get("title")), esc(g.get("why"))))
        parts.append("</ul></div>")

    parts.append("<h2>Quellen-Status</h2>")
    parts.append('<div class="card">')
    parts.append("<p>%s</p>" % esc(stats or "keine Statistik verfuegbar"))
    if failures:
        parts.append("<p><strong>Ausgefallene Feeds:</strong></p><ul>")
        for f in failures:
            parts.append("<li>%s</li>" % esc(f))
        parts.append("</ul>")
    else:
        parts.append("<p>Alle Feeds erreichbar.</p>")
    parts.append("</div>")

    parts.append('<footer>MySuricates Tech-Radar &middot; Run %s &middot; generiert %s</footer>'
                 % (esc(run_id), datetime.now().strftime("%d.%m.%Y %H:%M")))
    parts.append("</main>")
    body = "\n".join(parts)
    return ('<!DOCTYPE html><html lang="de"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width, initial-scale=1">'
            "<title>Tech-Radar KW %d/%d</title><style>%s</style></head><body>%s</body></html>"
            % (kw, report_date.year, CSS, body))


def render_index(archive_dir):
    entries = []
    for fn in os.listdir(archive_dir):
        m = re.match(r"^(\d{4})-(\d{2})-(\d{2})-tech-radar\.html$", fn)
        if not m:
            continue
        d = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        entries.append((d, fn))
    entries.sort(reverse=True)
    items = "\n".join(
        '<li><a href="archive/%s"><strong>KW %d/%d</strong></a> &mdash; Ausgabe vom %s</li>'
        % (fn, d.isocalendar()[1], d.year, d.strftime("%d.%m.%Y"))
        for d, fn in entries)
    body = ("<main><h1>Tech-Radar &middot; Archiv</h1>"
            '<p class="sub">W&ouml;chentlicher Awareness- &amp; Lernhappen-Radar &middot; %d Ausgaben</p>'
            '<div class="card"><ul class="plain">%s</ul></div>'
            "<footer>MySuricates Tech-Radar</footer></main>" % (len(entries), items))
    return ('<!DOCTYPE html><html lang="de"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width, initial-scale=1">'
            "<title>Tech-Radar Archiv</title><style>%s</style></head><body>%s</body></html>"
            % (CSS, body))


def update_seen(outdir, curate, deepen, report_date):
    seen_path = os.path.join(outdir, "seen.json")
    seen = {}
    if os.path.exists(seen_path):
        try:
            seen = json.load(open(seen_path, encoding="utf-8"))
        except Exception:
            seen = {}
    today = report_date.isoformat()
    urls = []
    for item in (curate or {}).get("digest") or []:
        urls.append(item.get("url"))
    for item in (curate or {}).get("top3") or []:
        urls.append(item.get("url"))
    for item in (deepen or {}).get("gaps") or []:
        urls.append(item.get("url"))
    for u in urls:
        if u:
            seen[u] = today
    cutoff = (report_date - timedelta(days=90)).isoformat()
    seen = {u: d for u, d in seen.items() if d >= cutoff}
    with open(seen_path, "w", encoding="utf-8") as f:
        json.dump(seen, f, ensure_ascii=False, indent=1, sort_keys=True)
    return len(seen)


def main():
    workdir, outdir = sys.argv[1], sys.argv[2]
    params = parse_params(os.path.join(workdir, "params.txt"))
    run_id = params.get("run_id", "?")
    stamp = params.get("run_stamp", "")
    try:
        report_date = datetime.strptime(stamp[:8], "%Y%m%d").date()
    except ValueError:
        report_date = date.today()

    curate, curate_err = load_json(os.path.join(workdir, "curate.raw"), "curate")
    if curate_err:
        print("FEHLER: %s" % curate_err, file=sys.stderr)
        sys.exit(1)
    deepen, deepen_err = load_json(os.path.join(workdir, "deepen.raw"), "deepen")
    failures, stats = parse_collect_meta(os.path.join(workdir, "collect.raw"))

    archive_dir = os.path.join(outdir, "archive")
    os.makedirs(archive_dir, exist_ok=True)
    report_path = os.path.join(archive_dir, "%s-tech-radar.html" % report_date.isoformat())
    with open(report_path, "w", encoding="utf-8") as f:
        f.write(render_report(curate, deepen, deepen_err, failures, stats, report_date, run_id))
    index_path = os.path.join(outdir, "index.html")
    with open(index_path, "w", encoding="utf-8") as f:
        f.write(render_index(archive_dir))
    n_seen = update_seen(outdir, curate, deepen, report_date)

    print("Report: %s" % report_path)
    print("Index:  %s" % index_path)
    print("seen.json: %d Eintraege" % n_seen)
    if deepen_err:
        print("Hinweis: deepen unbrauchbar -> Digest-only (%s)" % deepen_err)


if __name__ == "__main__":
    main()

MYS_RENDER_EOF

python3 "$RUN_DIR/render.py" "$RUN_DIR" "$OUT_DIR"
